select json_build_object('catalog',(select count(*) from public.anp_station_catalog),'mapped',(select count(*) from public.anp_station_catalog where station_id is not null),'review',(select count(*) from public.anp_station_catalog where station_id is null),'anp_visible',(select count(*) from public.stations where source_kind='anp' and status='verified'),'community',(select count(*) from public.stations where source_kind='community'),'anp_prices',(select count(*) from public.price_submissions p join public.stations s on s.id=p.station_id where s.source_kind='anp'))::text;
set role anon;
select json_build_object('near_bh',(select count(*) from public.nearby_stations_v3(-19.9,-43.95,10000,200,0)),'catalog_public_privileges',has_table_privilege('anon','public.anp_station_catalog','select'))::text;
